"""
Diagnostic complet de l'environnement Lean 4
Detecte les composants manquants et propose l'installation
"""

import subprocess
import shutil
import sys
import os
import platform
from pathlib import Path
from dataclasses import dataclass
from typing import Optional, List, Tuple

# Delai maximal accorde a une sonde de version. Le shim elan est la sonde la plus
# lente mesuree : 30 essais sous charge nominale donnent 0,58 s au maximum. Les
# echecs observes sous timeout=5 arrivent en salves de charge, donc bien au-dela
# du cout nominal. 30 s borne l'attente pathologique sans mordre le cas nominal.
PROBE_TIMEOUT_S = 30

@dataclass
class ComponentStatus:
    """Status d'un composant

    `measured=False` signale une sonde qui a echoue (delai depasse, erreur) :
    `installed` n'est alors pas une mesure, seulement un defaut de lecture.
    """
    name: str
    installed: bool
    version: Optional[str] = None
    path: Optional[str] = None
    error: Optional[str] = None
    can_auto_install: bool = False
    measured: bool = True

def check_python() -> ComponentStatus:
    """Verifie Python >= 3.8"""
    version = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
    ok = sys.version_info >= (3, 8)
    return ComponentStatus(
        name="Python",
        installed=ok,
        version=version,
        path=sys.executable,
        error=None if ok else "Python 3.8+ requis"
    )

def _check_binary(name: str, binary: str, on_unix_source_path: str, missing_hint: str) -> ComponentStatus:
    """Sonde un binaire (elan, lean) par ses deux voies d'acces.

    Voie 1 -- Linux/WSL : `source ~/.elan/env`, ou elan n'exporte pas toujours son
    repertoire dans le PATH du noyau.
    Voie 2 -- methode standard : `shutil.which` puis appel direct.

    Regle de verdict : une sonde qui ECHOUE (delai depasse, erreur d'execution) ne
    devient jamais une absence. "Absent" n'est rendu que si aucune voie n'a repondu
    et qu'aucune sonde n'a echoue -- on ne peut pas declarer absent ce qu'on n'a pas
    reussi a mesurer. Le code 127 ("commande introuvable") est la seule reponse qui
    vaut absence reelle sur la voie source.
    """
    unmeasured_reason = None

    def first_line(out: str) -> str:
        return out.strip().split('\n')[0]

    if platform.system() in ("Linux", "Darwin"):
        try:
            result = subprocess.run(
                ["bash", "-c", f"source ~/.elan/env 2>/dev/null && {binary} --version"],
                capture_output=True, text=True, timeout=PROBE_TIMEOUT_S, encoding="utf-8", errors="replace"
            )
        except subprocess.TimeoutExpired:
            unmeasured_reason = f"aucune reponse en {PROBE_TIMEOUT_S} s"
        except OSError as exc:
            unmeasured_reason = f"{type(exc).__name__} : {exc}"
        else:
            if result.returncode == 0:
                return ComponentStatus(name=name, installed=True,
                                       version=first_line(result.stdout),
                                       path=on_unix_source_path)
            if result.returncode != 127:
                unmeasured_reason = f"{binary} --version a rendu le code {result.returncode}"

    binary_path = shutil.which(binary)
    if binary_path:
        try:
            result = subprocess.run([binary, "--version"], capture_output=True, text=True,
                                    timeout=PROBE_TIMEOUT_S, encoding="utf-8", errors="replace")
            version = first_line(result.stdout) if result.returncode == 0 else "unknown"
            return ComponentStatus(name=name, installed=True, version=version, path=binary_path)
        except Exception as e:
            # Le binaire est la, la sonde n'a pas repondu : non mesure, jamais absent.
            return ComponentStatus(name=name, installed=True, path=binary_path,
                                   error=str(e), measured=False)

    if unmeasured_reason is not None:
        return ComponentStatus(name=name, installed=False, error=unmeasured_reason,
                               can_auto_install=False, measured=False)

    return ComponentStatus(
        name=name,
        installed=False,
        error=missing_hint,
        can_auto_install=True
    )

def check_elan() -> ComponentStatus:
    """Verifie si elan est installe"""
    return _check_binary("elan", "elan", "~/.elan/bin/elan", "elan non trouve dans PATH")

def check_lean() -> ComponentStatus:
    """Verifie si Lean 4 est installe"""
    return _check_binary("Lean 4", "lean", "~/.elan/bin/lean",
                         "lean non trouve (installez via elan)")

def check_lean4_jupyter() -> ComponentStatus:
    """Verifie si lean4_jupyter est installe"""
    try:
        import importlib.metadata
        version = importlib.metadata.version("lean4-jupyter")
        return ComponentStatus(name="lean4_jupyter", installed=True, version=version)
    except importlib.metadata.PackageNotFoundError:
        pass
    except Exception:
        pass

    # Fallback: essayer l'import
    try:
        import lean4_jupyter
        return ComponentStatus(name="lean4_jupyter", installed=True, version="unknown")
    except ImportError:
        return ComponentStatus(
            name="lean4_jupyter",
            installed=False,
            error="Module non installe",
            can_auto_install=True
        )

def check_jupyter_kernel() -> ComponentStatus:
    """Verifie si le kernel Lean est enregistre dans Jupyter"""
    try:
        result = subprocess.run(
            [sys.executable, "-m", "jupyter", "kernelspec", "list", "--json"],
            capture_output=True, text=True, timeout=PROBE_TIMEOUT_S, encoding="utf-8", errors="replace"
        )
        if result.returncode == 0:
            import json
            kernels = json.loads(result.stdout)
            kernel_names = list(kernels.get("kernelspecs", {}).keys())
            # Chercher lean4, lean4-wsl ou lean
            lean_kernel = next((k for k in kernel_names if "lean" in k.lower()), None)
            if lean_kernel:
                return ComponentStatus(
                    name="Kernel Jupyter",
                    installed=True,
                    version=lean_kernel,
                    path=kernels["kernelspecs"][lean_kernel].get("resource_dir")
                )
        return ComponentStatus(
            name="Kernel Jupyter",
            installed=False,
            error="Kernel Lean non enregistre",
            can_auto_install=True
        )
    except Exception as e:
        # Sonde en echec : le kernel n'est pas mesure. On ne propose pas de
        # l'installer -- installer ne repond pas a une sonde qui n'a pas repondu.
        return ComponentStatus(
            name="Kernel Jupyter",
            installed=False,
            error=f"sonde en echec ({type(e).__name__}) : {e}",
            can_auto_install=False,
            measured=False
        )

def run_diagnostic() -> Tuple[List[ComponentStatus], bool, List[str]]:
    """Execute le diagnostic complet"""
    print("=" * 60)
    print("    DIAGNOSTIC DE L'ENVIRONNEMENT LEAN 4")
    print("=" * 60)
    print(f"\nSysteme: {platform.system()} {platform.release()}")
    print(f"Architecture: {platform.machine()}")
    print()

    components = [
        check_python(),
        check_elan(),
        check_lean(),
        check_lean4_jupyter(),
        check_jupyter_kernel()
    ]

    print("-" * 60)
    print("Composant              Status         Version/Info")
    print("-" * 60)

    all_ok = True
    missing_installable = []
    indeterminate = []

    for c in components:
        if not c.measured:
            status = "[INDETERMINE]"
        elif c.installed:
            status = "[OK]"
        else:
            status = "[MANQUANT]"
        info = c.version or c.error or ""
        if c.path and c.installed:
            info = f"{info}" if info else c.path
        print(f"{c.name:<20}  {status:<14} {info[:40]}")

        if not c.measured:
            # Sonde ratee : ni present ni absent, et aucune installation proposee.
            indeterminate.append(c.name)
        elif not c.installed:
            all_ok = False
            if c.can_auto_install:
                missing_installable.append(c.name)

    print("-" * 60)

    if indeterminate:
        print(f"\n[~] Sonde(s) sans reponse : {', '.join(indeterminate)}")
        print(f"    Aucune reponse en {PROBE_TIMEOUT_S} s : ce n'est PAS une absence, et le")
        print("    composant n'a pas pu etre mesure. Re-executez ce diagnostic avant")
        print("    d'envisager une installation.")

    if all_ok and not indeterminate:
        print("\n[OK] Tous les composants sont installes !")
        print("     Vous pouvez passer aux notebooks suivants.")
    elif all_ok:
        print("\n[~] Aucun composant n'est mesure manquant (voir les sondes sans reponse ci-dessus).")
    else:
        print(f"\n[!] {len(missing_installable)} composant(s) manquant(s) peuvent etre installes automatiquement:")
        for name in missing_installable:
            print(f"    - {name}")
        print("\n    Executez la cellule 'Installation automatique' ci-dessous.")

    print("=" * 60)

    return components, all_ok, indeterminate

# Stocker le resultat pour utilisation ulterieure
DIAGNOSTIC_RESULTS, ALL_COMPONENTS_OK, INDETERMINATE_COMPONENTS = run_diagnostic()

"""
Detection et configuration du kernel Lean4 via WSL (Windows uniquement)

Sur Windows, le kernel lean4_jupyter natif peut avoir des problemes avec les chemins.
Ce script configure automatiquement un kernel WSL robuste pour Jupyter/VSCode.

Fonctionnalites du wrapper robuste:
- Conversion de chemins Windows vers WSL (y compris chemins "mangles")
- PATH propre sans pollution Windows
- Lancement direct via IPKernelApp (plus fiable que -m)
- Logging pour debugging (~/.lean4-wrapper.log)
"""

import subprocess
import platform
import json
import os
from pathlib import Path

def _detect_wsl_user() -> str:
    """Detect the WSL home directory dynamically (no hardcoded usernames)."""
    # Strategy 1: query $HOME from WSL
    try:
        result = subprocess.run(
            ["wsl.exe", "-d", "Ubuntu", "--", "bash", "-c", "echo -n $HOME"],
            capture_output=True, text=True, timeout=10, encoding="utf-8", errors="replace"
        )
        if result.returncode == 0 and result.stdout.strip().startswith("/"):
            return result.stdout.strip()
    except Exception:
        pass
    # Strategy 2: query whoami and construct /home/<user>
    try:
        result = subprocess.run(
            ["wsl.exe", "-d", "Ubuntu", "--", "whoami"],
            capture_output=True, text=True, timeout=10, encoding="utf-8", errors="replace"
        )
        if result.returncode == 0 and result.stdout.strip():
            return f"/home/{result.stdout.strip()}"
    except Exception:
        pass
    # Strategy 3: derive from Windows USERNAME env var (often matches WSL user)
    win_user = os.environ.get("USERNAME", os.environ.get("USER", ""))
    if win_user:
        return f"/home/{win_user.lower()}"
    # Last resort: use /root (WSL default when no user is set up)
    return "/root"

def _display_path(p) -> str:
    """Normalise un chemin pour l'affichage (home -> ~, separateurs /, pas de chemin machine)."""
    home = str(Path.home())
    s = str(p)
    s = "~" + s[len(home):] if s.startswith(home) else s
    return s.replace("\\", "/")

class WSLKernelManager:
    """Gestionnaire du kernel Lean4 via WSL avec wrapper robuste"""

    def __init__(self):
        self.is_windows = platform.system() == "Windows"
        self.kernel_name = "lean4-wsl"
        self.kernel_path = Path(os.environ.get("APPDATA", "")) / "jupyter" / "kernels" / self.kernel_name
        wsl_home = _detect_wsl_user() if self.is_windows else str(Path.home())
        self.wsl_home = wsl_home
        self.wrapper_path_wsl = f"{wsl_home}/.lean4-kernel-wrapper.py"
        self.venv_python = f"{wsl_home}/.lean4-venv/bin/python3"

    def _safe_decode(self, data: bytes) -> str:
        """Decode bytes safely, handling non-UTF8 characters from WSL"""
        return data.decode('utf-8', errors='replace')

    def _get_robust_wrapper_content(self) -> str:
        """Retourne le contenu du wrapper robuste en le chargeant depuis scripts/"""
        # Resolve script location dynamically from notebook directory
        notebook_dir = Path(globals().get("__vsc_ipynb_file__", str(Path.cwd()))).resolve().parent
        if not (notebook_dir / "scripts").exists():
            # Walk up to find the Lean directory
            current = Path.cwd().resolve()
            for _ in range(8):
                if (current / "scripts" / "lean4-kernel-wrapper.py").exists():
                    notebook_dir = current
                    break
                current = current.parent

        possible_paths = [
            notebook_dir / "scripts" / "lean4-kernel-wrapper.py",
            Path("scripts/lean4-kernel-wrapper.py"),  # Relatif au repertoire courant
        ]

        for wrapper_file in possible_paths:
            try:
                if wrapper_file.exists():
                    with open(wrapper_file, 'r', encoding='utf-8') as f:
                        return f.read()
            except Exception:
                continue

        raise FileNotFoundError(f"Wrapper script not found. Tried: {', '.join(_display_path(p) for p in possible_paths)}")

    def _create_wrapper_script(self) -> bool:
        """Deploie le script wrapper depuis scripts/ vers WSL via stdin"""
        try:
            # Charger le wrapper
            wrapper_content = self._get_robust_wrapper_content()

            # Ecrire via stdin WSL (evite les problemes d'echappement des heredoc)
            result = subprocess.run(
                ["wsl.exe", "-d", "Ubuntu", "bash", "-c", f"cat > {self.wrapper_path_wsl} && chmod +x {self.wrapper_path_wsl}"],
                input=wrapper_content,
                text=True,
                encoding="utf-8", errors="replace",
                capture_output=True,
                timeout=10
            )
            if result.returncode == 0:
                print(f"[+] Wrapper robuste deploye: {self.wrapper_path_wsl.replace(self.wsl_home, '~')}")
                return True
            print(f"[!] Erreur creation wrapper: {self._safe_decode(result.stderr)[:200]}")
            return False
        except FileNotFoundError as e:
            print(f"[!] {e}")
            print("    Assurez-vous que scripts/lean4-kernel-wrapper.py existe")
            return False
        except Exception as e:
            print(f"[!] Exception: {e}")
            return False


    def check_wsl_available(self) -> dict:
        """Verifie si WSL est disponible"""
        if not self.is_windows:
            return {"available": False, "reason": "Non Windows - WSL non necessaire"}

        try:
            result = subprocess.run(
                ["wsl.exe", "--status"],
                capture_output=True, timeout=10
            )
            if result.returncode == 0:
                return {"available": True, "reason": "WSL disponible"}
            return {"available": False, "reason": "WSL non configure"}
        except FileNotFoundError:
            return {"available": False, "reason": "WSL non installe"}
        except Exception as e:
            return {"available": False, "reason": str(e)}

    def check_wsl_lean_ready(self) -> dict:
        """Verifie si Lean est configure dans WSL"""
        try:
            result = subprocess.run(
                ["wsl.exe", "-d", "Ubuntu", "--", "bash", "-c",
                 "source ~/.elan/env 2>/dev/null && lean --version && which python3"],
                capture_output=True, timeout=30
            )
            stdout = self._safe_decode(result.stdout)

            if result.returncode == 0 and "Lean" in stdout:
                lines = stdout.strip().split('\n')
                lean_version = lines[0] if lines else "unknown"
                return {"ready": True, "lean_version": lean_version}
            return {"ready": False, "reason": "Lean non installe dans WSL"}
        except Exception as e:
            return {"ready": False, "reason": str(e)}

    def check_wsl_kernel_registered(self) -> dict:
        """Verifie si le kernel WSL est enregistre"""
        try:
            result = subprocess.run(
                [sys.executable, "-m", "jupyter", "kernelspec", "list", "--json"],
                capture_output=True, timeout=10
            )
            stdout = self._safe_decode(result.stdout)
            if result.returncode == 0:
                kernels = json.loads(stdout)
                if self.kernel_name in kernels.get("kernelspecs", {}):
                    return {
                        "registered": True,
                        "path": kernels["kernelspecs"][self.kernel_name].get("resource_dir")
                    }
            return {"registered": False}
        except Exception as e:
            return {"registered": False, "error": str(e)}

    def install_wsl_kernel(self, force: bool = False) -> bool:
        """Installe le kernel Lean4-WSL avec wrapper Python robuste."""
        print("[*] Installation du kernel Lean4-WSL...")

        # Deployer le wrapper robuste dans WSL
        if not self._create_wrapper_script():
            print("[!] Echec deploiement du wrapper")
            return False

        # Creer le dossier du kernel
        self.kernel_path.mkdir(parents=True, exist_ok=True)

        # Creer kernel.json qui utilise le venv Python et le wrapper
        kernel_json = {
            "argv": [
                "wsl.exe", "-d", "Ubuntu", "--",
                self.venv_python, self.wrapper_path_wsl,
                "-f", "{connection_file}"
            ],
            "display_name": "Lean 4 (WSL)",
            "language": "lean4"
        }

        kernel_file = self.kernel_path / "kernel.json"
        try:
            with open(kernel_file, 'w') as f:
                json.dump(kernel_json, f, indent=2)
        except OSError as e:
            print(f"[!] Erreur ecriture du kernelspec: {e}")
            return False

        print(f"[+] Kernel cree: {_display_path(kernel_file)}")
        return True

    def run_diagnostic(self):
        """Execute le diagnostic complet WSL et installe/met a jour le kernel"""
        print("=" * 60)
        print("    DIAGNOSTIC ET CONFIGURATION KERNEL LEAN4 VIA WSL")
        print("=" * 60)

        if not self.is_windows:
            print("\n[OK] Vous n'etes pas sur Windows.")
            print("     Utilisez le kernel lean4 standard.")
            return

        # 1. Verifier WSL
        print("\n[1/4] Verification de WSL...")
        wsl_status = self.check_wsl_available()
        if wsl_status["available"]:
            print(f"      [OK] {wsl_status['reason']}")
        else:
            print(f"      [!] {wsl_status['reason']}")
            print("\n      Pour installer WSL:")
            print("      wsl --install -d Ubuntu")
            return

        # 2. Verifier Lean dans WSL
        print("\n[2/4] Verification de Lean dans WSL...")
        lean_status = self.check_wsl_lean_ready()
        if lean_status.get("ready"):
            print(f"      [OK] {lean_status['lean_version']}")
        else:
            print(f"      [!] {lean_status.get('reason', 'Non configure')}")
            print("\n      Pour installer Lean dans WSL, executez dans WSL Ubuntu:")
            print("      curl -sSf https://raw.githubusercontent.com/leanprover/elan/master/elan-init.sh | sh")
            print("      source ~/.elan/env")
            print("      elan default leanprover/lean4:v4.11.0")
            print("      python3 -m venv ~/.lean4-venv")
            print("      source ~/.lean4-venv/bin/activate")
            print("      pip install lean4-jupyter ipykernel")
            return

        # 3. Installer/mettre a jour le kernel
        print("\n[3/4] Installation du kernel Jupyter...")
        kernel_status = self.check_wsl_kernel_registered()
        if kernel_status.get("registered"):
            print(f"      [OK] Kernel enregistre: {_display_path(kernel_status['path'])}")
            print("      [*] Mise a jour du wrapper robuste...")
        else:
            print("      [!] Kernel non enregistre")
            print("      [*] Installation automatique...")
        install_ok = self.install_wsl_kernel(force=True)

        if not install_ok:
            print("\n" + "=" * 60)
            print("[!] ECHEC a l'etape 3/4 : installation du kernel (deploiement du wrapper).")
            print("    Le kernel N'EST PAS pret a l'emploi.")
            print("    Cause frequente : scripts/lean4-kernel-wrapper.py introuvable")
            print("    depuis le repertoire courant -- reexecutez depuis le dossier du notebook.")
            print("=" * 60)
            return

        # 4. Tester le kernel
        print("\n[4/4] Test du kernel WSL...")
        test_ok = self._test_kernel()

        print("\n" + "=" * 60)
        if test_ok:
            print("[OK] Kernel Lean4-WSL pret a l'emploi !")
            print("\n     Dans VSCode:")
            print("     1. Rechargez la fenetre: Ctrl+Shift+P > 'Reload Window'")
            print("     2. Ouvrez un notebook .ipynb")
            print("     3. Cliquez sur 'Select Kernel' en haut a droite")
            print("     4. Choisissez 'Lean 4 (WSL)'")
            print("\n     Logs de debug: wsl cat ~/.lean4-wrapper.log")
        else:
            print("[~] Etape 4/4 echouee : kernel installe mais le test echoue.")
            print("    Redemarrez VSCode et reessayez.")
            print("    Verifiez les logs: wsl cat ~/.lean4-wrapper.log")
        print("=" * 60)

    def _test_kernel(self) -> bool:
        """Test rapide du kernel WSL"""
        try:
            result = subprocess.run(
                ["wsl.exe", "-d", "Ubuntu", "--", "bash", "-c",
                 f"source ~/.lean4-venv/bin/activate 2>/dev/null && "
                 f"source ~/.elan/env 2>/dev/null && "
                 f"python3 -c 'import lean4_jupyter; print(\"OK\")'"],
                capture_output=True, timeout=15
            )
            stdout = self._safe_decode(result.stdout)
            if "OK" in stdout:
                print("      [OK] lean4_jupyter fonctionne dans WSL")
                return True
            print(f"      [!] Erreur: {self._safe_decode(result.stderr)[:100]}")
            return False
        except Exception as e:
            print(f"      [!] Exception: {e}")
            return False

# Executer le diagnostic et configurer le kernel
wsl_manager = WSLKernelManager()
wsl_manager.run_diagnostic()

import os
import sys
from pathlib import Path

# --- Detection robuste du repertoire du notebook ---
# Fonctionne sous Windows, Linux, macOS et WSL (Epic #2314, Issue #2315)
notebook_dir = None

# Strategie 1: Variable environnement LEAN_NOTEBOOK_DIR
if os.getenv("LEAN_NOTEBOOK_DIR"):
    candidate = Path(os.getenv("LEAN_NOTEBOOK_DIR"))
    if candidate.exists() and (candidate / "lean_runner.py").exists():
        notebook_dir = candidate

# Strategie 2: Chercher dans cwd et parents (cross-platform)
if not notebook_dir:
    cwd = Path.cwd().resolve()
    current = cwd
    for _ in range(10):
        candidate = current / "MyIA.AI.Notebooks" / "SymbolicAI" / "Lean"
        if candidate.exists() and (candidate / "lean_runner.py").exists():
            notebook_dir = candidate
            break
        current = current.parent
        if current == current.parent:
            break

# Strategie 3: Recherche dynamique (Epic #2314, Issue #2315)
if not notebook_dir:
    _drive = Path.cwd().resolve().drive
    for _dl in ([_drive[0]] if _drive else ["c", "d"]):
        for _root in [f"{_dl}:/dev/CoursIA", f"{_dl.upper()}/dev/CoursIA"]:
            _cand = Path(_root) / "MyIA.AI.Notebooks" / "SymbolicAI" / "Lean"
            if _cand.exists() and (_cand / "lean_runner.py").exists():
                notebook_dir = _cand
                break
        if notebook_dir:
            break

if notebook_dir:
    # Chemin relatif au repo (machine-independant, pas de chemin absolu dans les sorties)
    try:
        _display_dir = notebook_dir.relative_to(notebook_dir.parents[2])
    except (IndexError, ValueError):
        _display_dir = notebook_dir.name
    print(f"Notebook dir: {_display_dir}")
    sys.path.insert(0, str(notebook_dir))
else:
    print("[!] Repertoire du notebook non trouve.")

# =============================================================================
# Vérification du cache LeanDojo
# =============================================================================
timer.start("Verification cache")
print("=" * 60)
print("VERIFICATION DU CACHE")
print("=" * 60)

cache_dir = Path.home() / ".cache" / "lean_dojo"
print(f"\nRepertoire cache: ~/{cache_dir.relative_to(Path.home())}")
print(f"Existe: {cache_dir.exists()}")

if cache_dir.exists():
    try:
        cache_contents = list(cache_dir.iterdir())
        print(f"Contenu: {len(cache_contents)} elements")

        if cache_contents:
            print("\nElements en cache:")
            for item in cache_contents[:5]:
                if item.is_dir():
                    size = sum(f.stat().st_size for f in item.rglob('*') if f.is_file()) / 1024 / 1024
                    print(f"  - {item.name} ({size:.1f} MB)")
                else:
                    print(f"  - {item.name}")
