def mono_ap(m, bits):
    # premiere progression arithmetique monochrome de longueur 3 (None sinon)
    for a in range(m):
        for d in range(1, m):
            if a + 2 * d >= m:
                break
            if bits[a] == bits[a + d] == bits[a + 2 * d]:
                return (a, a + d, a + 2 * d)
    return None

