# Encodeur Life + SAT enumeratif sur grille bornee.
# Specification : v = (2, -2), n = 8, grille W x H = 5 x 5.
# On cherche T : evolve n T = shift v T (sur la zone d'intersection).

W, H = 5, 5
N_PERIODS = 8
V = (2, -2)

def life_step(g):
    # Une generation de Life sur grille torique W x H.
    # Voisinage Moore 8-connexe.
    ngh = sum(np.roll(np.roll(g, di, 0), dj, 1)
              for di in (-1, 0, 1)
              for dj in (-1, 0, 1)
              if (di, dj) != (0, 0))
    return ((ngh == 3) | ((ngh == 2) & g)).astype(int)

def evolve(g, n):
    # n generations successives.
    cur = g.copy()
    for _ in range(n):
        cur = life_step(cur)
    return cur

def translate(g, v):
    # Translation (dx, dy) sur grille torique.
    dx, dy = v
    return np.roll(np.roll(g, dy, 0), dx, 1)

def is_translator(T, v, n):
    # Retourne True si T translate de v en n periodes.
    g0 = T.copy()
    for _ in range(n):
        g0 = life_step(g0)
    g_shifted = translate(T, v)
    return bool(np.array_equal(g0, g_shifted))

# Recherche par enumeration des sous-matrices 5x5 a densite <= 5
# (le glider canon fait 5 cellules vivantes).
print(f"Recherche translateur : v = {V}, n = {N_PERIODS}, grille = {W}x{H}")
print(f"Espace de recherche : 2^{W*H} = {2**(W*H):,} configurations")
print()

found_translators = []
# Elagage : on limite la densite (cellules vivantes <= 6, >= 4)
# Le glider canon a 5 cellules vivantes.
# Rejet du cas trivial (matrice vide) : densite >= 4.
MAX_DENSITY = 6
MIN_DENSITY = 4
n_tested = 0
for mask in range(2 ** (W * H)):
    # Decode le mask en matrice
    T = np.zeros((W, H), dtype=int)
    for k in range(W * H):
        if (mask >> k) & 1:
            T[k // H, k % H] = 1
    # Elagage par densite (rejet trivial)
    if T.sum() > MAX_DENSITY or T.sum() < MIN_DENSITY:
        continue
    n_tested += 1
    if is_translator(T, V, N_PERIODS):
        found_translators.append(T.copy())
        if len(found_translators) <= 10:
            print(f"Translateur trouve a densite {T.sum()} (test #{n_tested}):")
            print(T)
            print()

if len(found_translators) > 10:
    print(f"... ({len(found_translators) - 10} translateurs supplementaires trouves)")

print(f"Total configurations testees (apres elagage densite [{MIN_DENSITY}, {MAX_DENSITY}]) : {n_tested}")
print(f"Translateurs trouves (densite >= {MIN_DENSITY}) : {len(found_translators)}")

import math

M = 40  # profondeur commune des q-expansions

def mul(a, b):
    """Produit de deux series formelles, tronque a l'ordre M."""
    c = [0] * min(M + 1, len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            if i + j < len(c):
                c[i + j] += ai * bj
    return c

def powser(base, e):
    """Puissance e-ieme d'une serie formelle (exponentiation rapide)."""
    r = [1] + [0] * M
    b = base[:]
    while e:
        if e & 1:
            r = mul(r, b)
        b = mul(b, b)
        e >>= 1
    return r

def one_minus_qn(n):
    """Coefficients de (1 - q^n)."""
    out = [1] + [0] * M
    if n <= M:
        out[n] = -1
    return out

demo = mul([0, 1], [0, 1])  # q * q = q^2
print("q * q = coeff q^0..q^3 :", demo[:4])
assert demo[2] == 1 and sum(demo[:2]) == 0

def hecke_Tp_coeffs(a, p, k, depth):
    """Coefficients (T_p f)_n pour n = 1..depth, f de poids k, a[n] = a_n."""
    b = []
    for n in range(1, depth + 1):
        v = a[p * n] if p * n < len(a) else 0
        if n % p == 0:
            v += p ** (k - 1) * a[n // p]
        b.append(v)
    return b

for p, attendu in ((2, -24), (3, 252)):
    Tp = hecke_Tp_coeffs(tau, p, 12, 10)
    assert all(Tp[n - 1] == attendu * tau[n] for n in range(1, 11)), (p, Tp[:5])
    print(f"T_{p} Delta = {attendu} * Delta  -- verifie sur 10 coefficients (valeur propre tau({p}) = {attendu})")

def points_affines_E11(p):
    """Nombre de solutions affines (x, y) dans F_p x F_p de y^2 + y = x^3 - x^2 - 10x - 20."""
    return sum(1 for x in range(p) for y in range(p)
               if (y * y + y - (x ** 3 - x ** 2 - 10 * x - 20)) % p == 0)

def a_p_geom(p):
    """a_p = p + 1 - #E(F_p), point a l'infini inclus."""
    return p + 1 - (points_affines_E11(p) + 1)

