def plus_petit_premier_impair_divisant(n):
    """Plus petit facteur premier impair de n (n >= 3, impair non premier compris)."""
    for d in range(3, n + 1, 2):
        if n % d == 0 and all(d % q for q in range(2, int(d ** 0.5) + 1)):
            return d
    return None

