## 4. Surface de la sous-série : on mesure, on ne suppose rien

Un capstone sert à **décider si l'on entre**, et cette décision se prend sur des mesures, pas sur des promesses. La surface de la sous-série MIMO est ici recomptée depuis les sources du dépôt :

- nombre de carnets, lignes de code, exercices ;
- taille du lac, modules, énoncés `theorem` / `lemma` ;
- écart entre promesse (énoncés dans le README du lac) et un comptage direct (un `grep` sur `mimo_lean/` rend 57 là où l'**organe** `scripts/lean/scan_lake_notebook_visibility.py` en rend 56 — voir §5).

# Somme et produit euleriens partiels a s=2, meme seuil N : les deux membres mesurent pi^2/6.
def somme_partielle(s, n_max):
    """Somme des n^-s pour n <= n_max (mpmath, dps courant)."""
    return mp.fsum(mp.power(n, -s) for n in range(1, n_max + 1))

def produit_partiel(s, seuil_p):
    """Produit des (1 - p^-s)^-1 sur les premiers p <= seuil_p (mpmath)."""
    prod = mp.mpf(1)
    for p in PREMIERS:
        if p > seuil_p:
            break
        prod *= 1 / (1 - mp.power(p, -s))
    return prod

CIBLE_PI2_6 = mp.pi ** 2 / 6
print(f'{"N":>8} | {"err somme":>12} | {"err produit":>12} | {"rapport":>8}')
for N in (100, 1_000, 10_000):
    e_s = abs(somme_partielle(2, N) - CIBLE_PI2_6)
    e_p = abs(produit_partiel(2, N) - CIBLE_PI2_6)
    print(f'{N:>8} | {mp.nstr(e_s, 3):>12} | {mp.nstr(e_p, 3):>12} | {mp.nstr(e_s / e_p, 3):>8}')

def crible_premiers(n_max):
    # Sieve of Eratosthenes: list of primes <= n_max
    est_premier = [True] * (n_max + 1)
    est_premier[0] = est_premier[1] = False
    for i in range(2, int(n_max ** 0.5) + 1):
        if est_premier[i]:
            for j in range(i * i, n_max + 1, i):
                est_premier[j] = False
    return [i for i in range(n_max + 1) if est_premier[i]]

def von_mangoldt(n, premiers, ensemble_premiers):
    # Lambda(n) = ln p if n = p^k, else 0
    if n < 2:
        return 0.0
    for p in premiers:
        if p * p > n:
            break
        if n % p == 0:
            q = n
            while q % p == 0:
                q //= p
            return math.log(p) if q == 1 else 0.0
    return math.log(n) if n in ensemble_premiers else 0.0

PREMIERS_200 = crible_premiers(200)
ENSEMBLE_200 = set(PREMIERS_200)

support = [(n, von_mangoldt(n, PREMIERS_200, ENSEMBLE_200)) for n in range(2, 41)]
