def dirichlet_close(x, N):
    if abs(math.sin(x / 2)) < 1e-12:
        return 2 * N + 1.0
    return math.sin((N + 0.5) * x) / math.sin(x / 2)

def dirichlet_somme(x, N):
    return 1.0 + 2.0 * sum(math.cos(k * x) for k in range(1, N + 1))

