def simpson(g, a, b, m=4000):
    h = (b - a) / m
    s = g(a) + g(b) + 4 * g(a + h / 2)
    for k in range(1, m):
        s += (4 if k % 2 == 0 else 2) * g(a + k * h)
    return s * h / 3

