## Conclusion

Ce qu'on a distillé :

- **un corps fini** se manipule avec trois opérations, et l'inverse existe toujours ;
- **compter des points** sur $y^2 = x^3+ax+b$ est un calcul élémentaire — aucune théorie nécessaire pour produire les données ;
- **la borne de Hasse** $|t| \leq 2\sqrt{p}$, énoncé profond, se *vérifie* sur 1701 courbes en quelques secondes — et le nuage $|t|$ contre $2\sqrt{p}$ en porte la vue intuitive (fluctuations en $\sqrt{p}$) ;
- la **trace de Frobenius** condense l'arithmétique de la courbe : comptages sur toutes les extensions via $\alpha + \beta = t$, $\alpha\beta = p$.

C'est le geste de Serre que cette série veut honorer : rendre l'objet **calculable** avant de le généraliser — les corps finis d'*A Course in Arithmetic* jusqu'à la fonction zêta.
**L'autre geste, distillé du même talk : le contre-exemple est un théorème.** À l'IHP, Serre a défendu la notion contre l'idée qu'elle serait « quelque chose qui n'est pas bien » : « un contre-exemple, ça se lance, "il existe machin qui a telle propriété", c'est le théorème. Simplement, la propriété en question, les gens disaient : ah, on ne croyait pas que c'était vrai. Donc c'est en fait un résultat positif très intéressant » (talk du centenaire [10:03], transcription hors dépôt). L'exemple qui suit le rend sensible pour ce carnet : sur **corps fini**, Chevalley–Warning (1935) garantit le zéro non trivial d'un polynôme homogène dès que les variables dépassent le carré du degré — le monde dans lequel on calcule ici ; sur **corps $p$-adique**, le même énoncé (conjecture d'Artin) s'effondre en degré 4 par le contre-exemple de Terjanian — l'histoire en est distillée dans `07-zeros-fonctions-l-gaps-gue.ipynb`, section « La leçon du témoin faux ». Même énoncé, autre monde, autre vérité : une raison de plus de rendre chaque monde **calculable** avant de le croire.

def espace(elements, comparabilites):
    """Espace d'Alexandrov : ordre reflechi x <= y comme dict x -> {y}."""
    order = {x: {x} for x in elements}
    for a, b in comparabilites:
        order[a].add(b)
    return {"elements": list(elements), "order": order}

def ouvert_minimal(E, x):
    """U_x = {y : x <= y} : plus petit ouvert contenant x."""
    return frozenset(E["order"][x])

# L'espace de Sierpinski : a < b. Ouverts : vide, {b}, {a,b}.
sierpinski = espace(["a", "b"], [("a", "b")])
print("U_a =", sorted(ouvert_minimal(sierpinski, "a")),
      " U_b =", sorted(ouvert_minimal(sierpinski, "b")))
print("les U_x forment une base : {U_a, U_b} engendre les 3 ouverts")

def composantes(E, U):
    """Composantes connexes d'un ouvert U (union-find sur le graphe
    d'intersection des ouverts minimaux, restreint a U)."""
    pts = sorted(U)
    parent = {p: p for p in pts}

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for a, b in combinations(pts, 2):
        if (ouvert_minimal(E, a) & ouvert_minimal(E, b)) & U:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
    groupes = {}
    for p in pts:
        groupes.setdefault(find(p), []).append(p)
    return sorted((frozenset(g) for g in groupes.values()), key=lambda g: min(g))

def restriction(E, U, V):
    """Matrice Z^{pi0(U)} -> Z^{pi0(V)} du faisceau constant (0/1,
    ligne = composante de V, colonne = composante de U qui la contient)."""
    cu, cv = composantes(E, U), composantes(E, V)
    return [[1 if cvi <= cuj else 0 for cuj in cu] for cvi in cv]

# Sur le cercle a 4 points (modele minimal de McCord de S^1) :
cercle4 = espace(["a1", "a2", "a3", "a4"],
                 [("a1", "a2"), ("a1", "a4"), ("a3", "a2"), ("a3", "a4")])
tout = frozenset(cercle4["elements"])
print("pi0(cercle4 entier) :", [sorted(c) for c in composantes(cercle4, tout)])
inter = ouvert_minimal(cercle4, "a1") & ouvert_minimal(cercle4, "a3")
print("U_a1 & U_a3 =", sorted(inter), "-> pi0 :", [sorted(c) for c in composantes(cercle4, inter)])

def rang(M):
    """Rang exact d'une matrice d'entiers (elimination sur Q)."""
    if not M or not M[0]:
        return 0
    A = [[Fraction(v) for v in r] for r in M]
    rows, cols, r = len(A), len(A[0]), 0
    for c in range(cols):
        p = next((i for i in range(r, rows) if A[i][c] != 0), None)
        if p is None:
            continue
        A[r], A[p] = A[p], A[r]
        A[r] = [v / A[r][c] for v in A[r]]
        for i in range(rows):
            if i != r and A[i][c] != 0:
                f = A[i][c]
                A[i] = [a - f * b for a, b in zip(A[i], A[r])]
        r += 1
    return r

def produit(A, B):
    if not A or not B:
        return []
    return [[sum(Fraction(A[i][k]) * Fraction(B[k][j]) for k in range(len(B)))
             for j in range(len(B[0]))] for i in range(len(A))]

def complexe_cech(E, degre_max=2):
    """Bases explicites de C^k et differentielles (matrices d'entiers)."""
    pts = E["elements"]
    n = len(pts)
    ouvs = [ouvert_minimal(E, x) for x in pts]

    def cells(k):
        out = []
        for idx in combinations(range(n), k + 1):
            inter = frozenset.intersection(*[ouvs[i] for i in idx])
            if inter:
                out.append((idx, inter))
        return out

    bases = {k: [(idx, ci) for idx, o in cells(k)
                 for ci in range(len(composantes(E, o)))]
             for k in range(degre_max + 2)}
    col_of = {k: {b: j for j, b in enumerate(bases[k])} for k in bases}

    diffs = {}
    for k in range(degre_max + 1):
        M = [[0] * len(bases[k]) for _ in bases[k + 1]]
        for tgt_idx, o_tgt in cells(k + 1):
            for pos, i in enumerate(tgt_idx):
                src_idx = tuple(x for x in tgt_idx if x != i)
                src = next(((ix, o) for ix, o in cells(k) if ix == src_idx), None)
                if src is None:
                    continue  # intersection vide -> groupe nul
                R = restriction(E, src[1], o_tgt)
                sgn = 1 if pos % 2 == 0 else -1
                for li, row in enumerate(R):
                    for lj, v in enumerate(row):
                        if v:
                            M[col_of[k + 1][(tgt_idx, li)]][col_of[k][(src_idx, lj)]] += sgn * v
        diffs[k] = M
    return bases, diffs

def cohomologie_cech(E, degre_max=2):
    """Dimensions de H^0..H^{degre_max} + verification exacte d^{k+1}.d^k = 0."""
    bases, diffs = complexe_cech(E, degre_max)
    compose_nul = all(all(v == 0 for row in produit(diffs[k + 1], diffs[k]) for v in row)
                      for k in range(degre_max) if diffs[k] and diffs[k + 1])
    H = {}
    for k in range(degre_max + 1):
        H[k] = (len(bases[k]) - rang(diffs[k])
                - (rang(diffs[k - 1]) if k >= 1 else 0))
    return H, compose_nul

def ordre_complexe(E, degre_max=2):
    """Squelette du complexe d'ordre : sk[k] = k-simplexes = chaines croissantes."""
    pts, ordre = E["elements"], E["order"]
    chaines = {k: set() for k in range(degre_max + 2)}
    for x in pts:
        pile = [(x,)]
        chaines[0].add((x,))
        while pile:
            ch = pile.pop()
            for y in ordre[ch[-1]]:
                if y != ch[-1]:
                    ch2 = ch + (y,)
                    chaines[len(ch2) - 1].add(ch2)
                    pile.append(ch2)
    return {k: sorted(chaines[k]) for k in chaines}

def cobords_ordre(sk, degre_max=2):
    """Matrices de cobord : delta^k a pour lignes les (k+1)-simplexes."""
    deltas = {}
    for k in range(degre_max):
        M = [[0] * len(sk[k]) for _ in sk[k + 1]]
        for ti, t in enumerate(sk[k + 1]):
            for pos in range(len(t)):
                s = t[:pos] + t[pos + 1:]
                if s in set(sk[k]):
                    M[ti][sk[k].index(s)] += 1 if pos % 2 == 0 else -1
        deltas[k] = M
    return deltas

def cohomologie_ordre(E, degre_max=2):
    """Cohomologie du complexe d'ordre sur Q : dimensions par elimination exacte."""
    sk = ordre_complexe(E, degre_max)
    deltas = cobords_ordre(sk, degre_max)
    H = {}
    for k in range(degre_max + 1):
        H[k] = (len(sk[k]) - rang(deltas[k] if k in deltas else [])
                - (rang(deltas[k - 1]) if k >= 1 else 0))
    return H

# Tableau croise : les deux machines doivent s'accorder sur les trois espaces.
lignes = []
for nom, E in [("Sierpinski", sierpinski), ("Cercle 4 pts", cercle4), ("Sphere-tetraedre", tetra)]:
    Hc, ok = cohomologie_cech(E)
    Hs = cohomologie_ordre(E)
    lignes.append((nom, Hc, Hs, "ACCORD" if Hc == Hs else "DIVERGENCE"))
print(f"{'espace':16s} {'Cech (faisceaux)':24s} {'ordre (simplicial)':22s} verdict")
for nom, Hc, Hs, v in lignes:
    print(f"{nom:16s} {str(Hc):24s} {str(Hs):22s} {v}")

# --- 1. Noyau entier : forme normale de Smith -------------------------------
def smith(M):
    """Forme normale de Smith entiere : rend (D, U, V) avec U M V = D,
    U et V unimodulaires, D diagonale (facteurs invariants)."""
    A = [[int(v) for v in row] for row in M]
    m, n = len(A), (len(A[0]) if A else 0)
    U = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    V = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    if m == 0 or n == 0:
        return A, U, V

    def echange_lignes(i, j):
        A[i], A[j] = A[j], A[i]
        U[i], U[j] = U[j], U[i]

    def echange_colonnes(i, j):
        for r in range(m):
            A[r][i], A[r][j] = A[r][j], A[r][i]
        for r in range(n):
            V[r][i], V[r][j] = V[r][j], V[r][i]

    def retranche_ligne(i, j, q):
        if q:
            for c in range(n):
                A[i][c] -= q * A[j][c]
            for c in range(m):
                U[i][c] -= q * U[j][c]

    def retranche_colonne(i, j, q):
        if q:
            for r in range(m):
                A[r][i] -= q * A[r][j]
            for r in range(n):
                V[r][i] -= q * V[r][j]

    t = 0
    while t < min(m, n):
        pivot = None
        for i in range(t, m):
            for j in range(t, n):
                if A[i][j] != 0:
                    pivot = (i, j)
                    break
            if pivot:
                break
        if pivot is None:
            break
        echange_lignes(t, pivot[0])
        echange_colonnes(t, pivot[1])
        while True:
            change = False
            for i in range(t + 1, m):
                if A[i][t] != 0:
                    retranche_ligne(i, t, A[i][t] // A[t][t])
                    if A[i][t] != 0:        # reste non nul : on echange les lignes
                        echange_lignes(t, i)
                        change = True
            for j in range(t + 1, n):
                if A[t][j] != 0:
                    retranche_colonne(j, t, A[t][j] // A[t][t])
                    if A[t][j] != 0:
                        echange_colonnes(t, j)
                        change = True
            if not change:
                break
        t += 1
    return A, U, V


def facteurs(D):
    """Facteurs invariants non nuls d'une matrice diagonale de Smith."""
    n = min(len(D), len(D[0]) if D else 0)
    return [abs(D[i][i]) for i in range(n) if D[i][i] != 0]


def noyau_colonnes(M):
    """Base entiere de ker M : les colonnes de V situees au-dela du rang."""
    D, _, V = smith(M)
    r = len(facteurs(D))
    n = len(V)
    return [[V[i][j] for i in range(n)] for j in range(r, n)]


# Auto-test de la machine : la convention U M V = D, et U unimodulaire.
for _M in ([[2]], [[1, 2, 3], [4, 5, 6]], [[2, 4], [6, 8]]):
    _D, _U, _V = smith(_M)
    assert produit(produit(_U, _M), _V) == [[Fraction(v) for v in r] for r in _D], \
        "convention U M V = D violee sur %s" % (_M,)
    assert facteurs(smith(_U)[0]) == [1] * len(_U), "U n'est pas unimodulaire"
print("auto-test Smith : U M V = D verifie, U unimodulaire (3 matrices)")


# --- 2 et 3. Coordonnees exactes, puis quotient -----------------------------
def resoudre_exact(K, g):
    """Resout K x = g exactement, K a colonnes independantes (Gauss-Jordan sur Q)."""
    m = len(K)
    p = len(K[0]) if m else 0
    aug = [[Fraction(K[i][j]) for j in range(p)] + [Fraction(g[i])] for i in range(m)]
    ligne = 0
    for col in range(p):
        pivot = next((i for i in range(ligne, m) if aug[i][col] != 0), None)
        if pivot is None:
            continue
        aug[ligne], aug[pivot] = aug[pivot], aug[ligne]
        pv = aug[ligne][col]
        aug[ligne] = [v / pv for v in aug[ligne]]
        for i in range(m):
            if i != ligne and aug[i][col] != 0:
                f = aug[i][col]
                aug[i] = [a - f * b for a, b in zip(aug[i], aug[ligne])]
        ligne += 1
    x = [Fraction(0)] * p
    ligne = 0
    for col in range(p):
        pivot = next((i for i in range(ligne, m) if aug[i][col] != 0), None)
        if pivot is not None:
            x[col] = aug[pivot][p]
            ligne += 1
    return x


def quotient_invariants(base_noyau, generateurs):
    """Z^p / <coordonnees des generateurs dans base_noyau> -> (rang libre, torsion).

    base_noyau est une liste de COLONNES ; on en fait la matrice avant de resoudre.
    """
    p = len(base_noyau)
    if p == 0:
        assert not generateurs, "l'image deborde d'un noyau nul"
        return 0, []
    K = [[base_noyau[j][i] for j in range(p)] for i in range(len(base_noyau[0]))]
    X = []
    for g in generateurs:
        x = resoudre_exact(K, g)
        assert all(v.denominator == 1 for v in x), "coordonnee non entiere"
        assert all(sum(K[i][j] * x[j] for j in range(p)) == g[i]
                   for i in range(len(K))), "resolution fausse"
        X.append([int(v) for v in x])
    if not X:
        return p, []
    Xc = [[X[j][i] for j in range(len(X))] for i in range(p)]
    inv = facteurs(smith(Xc)[0])
    return p - len(inv), [d for d in inv if d > 1]


def cohomologie_ordre_Z(E, degre_max=2):
    """H^k du complexe d'ordre sur Z : (rang libre, facteurs de torsion) par degre."""
    sk = ordre_complexe(E, degre_max)
    deltas = cobords_ordre(sk, degre_max)
    groupes = {}
    for k in range(degre_max + 1):
        if k in deltas and deltas[k]:
            noyau = noyau_colonnes(deltas[k])
        else:
            # degre maximal : pas de (k+1)-simplexes, donc ker delta^k = C^k entier
            noyau = [[1 if i == j else 0 for i in range(len(sk[k]))]
                     for j in range(len(sk[k]))]
        image = []
        if k - 1 in deltas and deltas[k - 1] and deltas[k - 1][0]:
            M = deltas[k - 1]
            image = [[M[i][j] for i in range(len(M))] for j in range(len(M[0]))]
        groupes[k] = quotient_invariants(noyau, image)
    return groupes, sk, deltas


def fmt_groupes(groupes):
    """Rend 'H^0 = Z ; H^1 = Z + Z/2' pour un dict degre -> (rang libre, torsion)."""
    morceaux = []
    for k in sorted(groupes):
        libre, torsion = groupes[k]
        termes = []
        if libre:
            termes.append("Z" if libre == 1 else "Z^%d" % libre)
        termes.extend("Z/%d" % d for d in torsion)
        morceaux.append("H^%d = %s" % (k, " + ".join(termes) if termes else "0"))
    return " ; ".join(morceaux)

print("Z --x2--> Z :", quotient_invariants([[1]], [[2]]), "(cokernel attendu (0, [2]))")

## Conclusion

Ce qu'on a distillé :

- un **espace topologique fini** est un poset ; sa topologie tient dans la relation d'ordre (ouverts minimaux) ;
- le **faisceau constant** s'y calcule : sections $= \mathbb{Z}^{\pi_0}$, restrictions $=$ matrices $0/1$ d'inclusion de composantes ;
- le **complexe de Čech** du recouvrement minimal donne des matrices d'entiers ; l'élimination exacte sur $\mathbb{Q}$ en tire les **nombres de Betti** $b_k = \dim_{\mathbb{Q}} H^k(;\mathbb{Q})$ — test structurel $\delta^2 \delta^1 = 0$ garantit la cohérence ;
- les nombres de Betti ne **déterminent pas** le groupe : $H^k(;\mathbb{Z})$ peut porter de la **torsion** invisible à $\mathbb{Q}$. Pour Sierpiński, $S^1$ et $S^2$, McCord 1967 garantit l'absence de torsion (rangs = groupes) ; $\mathbb{RP}^2$ est le contre-exemple — $b_1 = b_2 = 0$ **et pourtant** $H^2(\mathbb{RP}^2;\mathbb{Z}) = \mathbb{Z}/2$ ;
- la **machine sur $\mathbb{Z}$** décide ce que Čech-sur-$\mathbb{Q}$ ne pouvait que déclarer hors de portée : noyau entier, coordonnées exactes, forme normale de Smith du quotient. Le $\mathbb{Z}/2$ n'est pas postulé, c'est un **facteur invariant** de $\delta^1$ lu dans sa diagonalisation ;
- le **modèle** lui-même est vérifié et non supposé : la triangulation à 6 sommets (chaque arête dans exactement 2 triangles, lien de chaque sommet cyclique, $\chi = 1$) est identifiée à $\mathbb{RP}^2$ par le théorème de classification, et son poset des faces (31 éléments) a pour complexe d'ordre sa subdivision barycentrique ;
- le théorème de **McCord** (équivalence faible avec le complexe d'ordre) est ce qui rend les deux machines d'accord sur les espaces sans torsion ;

C'est le pont Serre–Grothendieck de l'EPIC [#16334](https://github.com/jsboige/CoursIA/issues/16334) : le langage de FAC — faisceaux, recouvrements, cohomologie — démontré en Lean dans `grothendieck_lean`, calculé ici en Python pur, sur les mêmes objets.

def categorie(obj, hom, idn, comp):
    """Categorie finie : hom[(a,b)] = tuple des fleches a->b,
    idn[x] = fleche identite, comp[(g,f)] = g . f pour g: b->c, f: a->b."""
    return {"obj": list(obj), "hom": hom, "idn": idn, "comp": comp}

def cat_poset(P):
    """Poset (dict x -> {y : x <= y}) vu comme categorie : 0 ou 1 fleche par paire."""
    obj = list(P)
    hom, idn, comp = {}, {}, {}
    for a in obj:
        for b in obj:
            if b in P[a]:
                hom[(a, b)] = ((a, b),)
    for x in obj:
        idn[x] = (x, x)
    for (a, b), _ in hom.items():
        for (b2, c), _ in hom.items():
            if b2 == b:
                comp[((b, c), (a, b))] = (a, c)
    return categorie(obj, hom, idn, comp)

def cat_monoide(elements, produit, neutre):
    """Monoide vu comme categorie a un objet '*'."""
    return categorie(["*"],
                     {("*", "*"): tuple(elements)},
                     {"*": neutre},
                     {(f, g): produit(f, g) for f in elements for g in elements})

def hom_set(C, a, b):
    return C["hom"].get((a, b), ())

# Espace de Sierpinski a<b en categorie, et le groupe Z/2 en categorie :
sierpinski = cat_poset({"a": {"a", "b"}, "b": {"b"}})
z2 = cat_monoide(["e", "t"], lambda u, v: ("e" if u == v else "t"), "e")
print("Sierpinski : fleches", {k: v for k, v in sierpinski['hom'].items()})
print("Z/2 : fleches", z2["hom"][("*", "*")], "- composition t.t =", z2["comp"][("t", "t")])

def foncteur(C, ensembles, actions):
    """ensembles[x] : frozenset ; actions[fleche] : dict ensemble source -> cible."""
    return {"ens": ensembles, "act": actions}

def h_X(C, X):
    """Representable covariant Hom(X, -) : ens(Y) = fleches X->Y,
    act[g: a->b] : Hom(X,a) -> Hom(X,b), f |-> g . f (post-composition)."""
    ens = {y: frozenset(hom_set(C, X, y)) for y in C["obj"]}
    act = {}
    for (a, b), fs in C["hom"].items():
        for g in fs:
            act[g] = {f: C["comp"][(g, f)] for f in hom_set(C, X, a)
                      if (g, f) in C["comp"]}
    return foncteur(C, ens, act)

# Le representable du point generique 'a' de Sierpinski :
ha = h_X(sierpinski, "a")
for y in sierpinski["obj"]:
    print(f"h_a({y}) = {sorted(ha['ens'][y])}")
# et un foncteur temoin : la permutation (1 2) le long de a -> b
F_swap = foncteur(sierpinski,
                  {"a": frozenset({1, 2}), "b": frozenset({1, 2})},
                  {("a", "b"): {1: 2, 2: 1}, ("a", "a"): {1: 1, 2: 2},
                   ("b", "b"): {1: 1, 2: 2}})

def transformations_naturelles(C, F, G):
    """Toutes les familles alpha_y : F(y) -> G(y) naturelles (enumeration exhaustive)."""
    obj = C["obj"]

    def fonctions(src, tgt):
        if not tgt:
            return [{}] if not src else []
        return [dict(zip(src, vals)) for vals in product(tgt, repeat=len(src))]

    composantes = [fonctions(F["ens"][y], G["ens"][y]) for y in obj]
    resultat = []
    for combo in product(*composantes):
        alpha = dict(zip(obj, combo))
        ok = True
        for (a, b), fs in C["hom"].items():
            for g in fs:
                Fa, Ga = F["act"].get(g, {}), G["act"].get(g, {})
                for x in F["ens"][a]:
                    if Ga.get(alpha[a].get(x)) != alpha[b].get(Fa.get(x)):
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                break
        if ok:
            resultat.append(alpha)
    return resultat

# Premiere mesure : sur Sierpinski, |Nat(h_X, F)| pour deux foncteurs temoins.
F_const3 = foncteur(sierpinski,
                    {"a": frozenset({0, 1, 2}), "b": frozenset({0, 1, 2})},
                    {("a", "b"): {0: 0, 1: 1, 2: 2}, ("a", "a"): {0: 0, 1: 1, 2: 2},
                     ("b", "b"): {0: 0, 1: 1, 2: 2}})
for X in ["a", "b"]:
    hX = h_X(sierpinski, X)
    for nom, F in [("swap", F_swap), ("const3", F_const3)]:
        nats = transformations_naturelles(sierpinski, hX, F)
        print(f"X={X} F={nom:8s} : |Nat(h_X,F)| = {len(nats)}  |  |F(X)| = {len(F['ens'][X])}")

for x in ["a1", "a3"]:
    hx = h_X(cercle4, x)
    support = {y for y in cercle4["obj"] if hx["ens"][y]}
    u_x = {y for y in cercle4["obj"] if hom_set(cercle4, x, y)}
    print(f"x={x} : support de h_x = {sorted(support)} == U_x : {support == u_x}")

## Conclusion

Ce qu'on a distillé :

- une **catégorie finie** tient en trois dictionnaires (objets, hom-sets, composition) ; posets et monoïdes en sont les exemples rois ;
- les **transformations naturelles** entre foncteurs vers les ensembles finis s'**énumèrent exhaustivement** — le filtrage par les carrés commutatifs est la seule force du calcul ;
- le **lemme de Yoneda** se vérifie alors comme une mesure : $|\mathrm{Nat}(h_X, F)| = |F(X)|$, l'évaluation $\alpha \mapsto \alpha_X(\mathrm{id}_X)$ est bijective, son inverse explicite round-trip — sur des posets, sur le monoïde $\mathbb{Z}/2$ ;
- **plein et fidèle** : $|\mathrm{Nat}(h_X, h_Y)| = |\mathrm{Hom}(Y, X)|$, matrice mesurée sur le cercle à 4 points — le plongement $X \mapsto h_X$ ne perd rien ;
- le **pont Čech** : pour un poset, le support du représentable $h_x$ est l'ouvert minimal $U_x$ — le recouvrement du notebook 03 est l'image du plongement de Yoneda.

Le même énoncé, démontré en Lean dans `grothendieck_lean/YonedaLemma.lean`, calculé ici en Python pur. C'est le grain 8 de la voie décorrelée Serre–Grothendieck de l'EPIC [#16334](https://github.com/jsboige/CoursIA/issues/16334) — après le grain 7 (Čech calculée), le geste catégorique devient machine.

# ============================================================
# Outils : combinatoire des partitions, en stdlib pure.
# Une partition lam = (l1 >= l2 >= ...) est un diagramme de Young
# en coordonnees (ligne, colonne), ligne 0 en haut.
# ============================================================
from fractions import Fraction as Fr
from itertools import combinations

def cells_of(lam):
    '''Les cases du diagramme de lam.'''
    return {(r, c) for r, row in enumerate(lam) for c in range(row)}

def rim_cells(lam):
    '''Le bord du diagramme : cases sans voisine en bas-a-droite.'''
    cl = cells_of(lam)
    return {(r, c) for (r, c) in cl if (r + 1, c + 1) not in cl}

def connected(sub):
    '''Connectivite par aretes (partage d'un cote).'''
    if not sub:
        return False
    sub = set(sub)
    start = next(iter(sub))
    seen = {start}
    stack = [start]
    while stack:
        (r, c) = stack.pop()
        for nb in [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]:
            if nb in sub and nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return len(seen) == len(sub)

def remove_rim_hooks(lam, k):
    '''Toutes les facons d'oter du bord de lam une equerre connectee de k cases,
    en laissant un vrai diagramme. Rend la liste des (diagramme restant, hauteur).'''
    rc = sorted(rim_cells(lam))
    out = []
    for H in combinations(rc, k):
        H = set(H)
        rest = cells_of(lam) - H
        if not rest:
            new_lam = ()
        else:
            maxr = max(r for r, _ in rest)
            lengths = [max([c for (rr, c) in rest if rr == r], default=-1) + 1
                       for r in range(maxr + 1)]
            if 0 in lengths:          # trou : pas un diagramme de Young
                continue
            new_lam = tuple(lengths)
        # le reste doit etre ferme vers le haut-gauche, l'equerre connectee
        ok = all((r, c - 1) in rest or c == 0 for (r, c) in rest) and \
             all((r - 1, c) in rest or r == 0 for (r, c) in rest)
        if not ok or not connected(H):
            continue
        height = len({r for (r, _) in H})
        out.append((new_lam, height))
    return out

def mn_char(lam, mu):
    '''chi^lam(mu) par la regle de Murnaghan-Nakayama, recursive sur le type mu.'''
    lam, mu = tuple(lam), tuple(mu)
    if not mu:
        return 1 if sum(lam) == 0 else 0
    if sum(lam) == 0:
        return 0
    k, rest_mu = mu[0], mu[1:]
    total = 0
    for (reste, h) in remove_rim_hooks(lam, k):
        total += (-1) ** (h - 1) * mn_char(reste, rest_mu)
    return total

def partitions(n, max_part=None):
    '''Les partitions de n en parts <= max_part, ordre lexicographique decroissant.'''
    if max_part is None or max_part > n:
        max_part = n
    if n == 0:
        yield ()
        return
    for first in range(min(max_part, n), 0, -1):
        for rest in partitions(n - first, first):
            yield (first,) + rest

print("Outils charges :", len(list(partitions(4))), "partitions de 4 =", list(partitions(4)))
print("Exemple MN : chi^(2,1) sur la classe (3) de S3 vaut", mn_char((2, 1), (3,)))

