## 3. LP naïf sur grilles : ce que le solveur fait quand on ne certifie pas

On approche le programme de Cohn–Elkies par un LP fini : un **dictionnaire de Gaussiennes** $f = \sum_i a_i\, g_i$ avec $g_i(x) = e^{-\pi c_i x^2}$ (fonction radiale de $|x|$), et les contraintes **posées aux points d'une grille** uniquement :

- minimiser $f(0) = \sum a_i$ sous $\widehat f(0) = \sum a_i c_i^{-n/2} = 1$ ;
- $f(t_j) \le 0$ sur une grille $t_j \ge 1$ ; $\widehat f(s_j) \ge 0$ sur une grille $s_j \ge 0$ ;
- coefficients à signe libre, bornés en masse : $\sum |a_i| \le L^1$.

Si cette relaxation était fidèle, toute borne produite serait un théorème. La cellule suivante mesure qu'il n'en est rien : les contraintes ne portent que sur la grille, et **tout ce qui n'est pas contraint est exploité**.

# Noyau 2 : decomposition p = a^2 + b^2 pour p premier, p = 1 mod 4.
# On utilise Cornacchia : a partir de u avec u^2 = -1 mod p, on applique Euclide
# (p, u) tant que le reste excede sqrt(p). Le reste final r verifie r^2 + s^2 = p
# ou s est un reste anterieur de la division.
from math import isqrt

def two_squares(p):
    """Decompose p = a^2 + b^2 (a >= b > 0), ou None si pas de representation."""
    if p == 2:
        return (1, 1)
    if p % 4 == 3:
        return None
    # p = 1 mod 4 : trouver u avec u^2 = -1 mod p
    u = None
    for v in range(2, p):
        if (v * v) % p == p - 1:
            u = v
            break
    if u is None:
        return None  # securite -- ne devrait pas arriver pour p = 1 mod 4
    # Cornacchia : Euclide (p, u) tant que reste^2 > p
    a, b = p, u
    while b * b > p:
        a, b = b, a % b
    # Maintenant b^2 <= p ; il faut trouver s tel que b^2 + s^2 = p.
    reste = p - b * b
    s = isqrt(reste)
    if s * s != reste:
        # Securite : Cas pathologique non couvert.  Arithmetique Cornacchia complete :
        # Le s est le coefficient d'Euclide au pas ou b devient <= sqrt(p).
        # On relance avec une autre racine u.
        for v in range(u + 1, p):
            if (v * v) % p == p - 1:
                a, b = p, v
                while b * b > p:
                    a, b = b, a % b
                reste = p - b * b
                s = isqrt(reste)
                if s * s == reste:
                    return (max(b, s), min(b, s))
        return None
    return (max(b, s), min(b, s))

# Verification sur tous les premiers p <= 1000.
def premiers(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, isqrt(n) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False
    return [i for i in range(2, n + 1) if sieve[i]]

ok = 0; rep_1mod4 = 0; rep_3mod4 = 0; rep_2 = 0
echecs = []
for p in premiers(1000):
    r = two_squares(p)
    if p == 2:
        rep_2 += 1
        if r == (1, 1):
            ok += 1
    elif p % 4 == 1:
        rep_1mod4 += 1
        if r and r[0] ** 2 + r[1] ** 2 == p and r[0] > 0 and r[1] > 0:
            ok += 1
        else:
            echecs.append((p, r))
    else:
        rep_3mod4 += 1
        if r is None:
            ok += 1

print(f"p <= 1000 : {rep_1mod4} premiers = 1 mod 4, {rep_3mod4} premiers = 3 mod 4, {rep_2} pour p = 2")
print(f"Verification du theoreme des deux carres : {ok}/{rep_1mod4 + rep_3mod4 + rep_2}")
if echecs:
    print(f"Echecs (p, representation) : {echecs[:5]}")
else:
    print("Aucun echec : tous les premiers <= 1000 sont traites correctement")

# Noyau 3 : decomposition p = a^2 + ab + b^2 pour p premier, p = 1 mod 3.
def two_triangles(p):
    """Decompose p = a^2 + ab + b^2 (a, b > 0), ou None."""
    if p == 3:
        return (1, 1)  # 3 = 1^2 + 1*1 + 1^2
    if p % 3 == 2:
        return None
    # p = 1 mod 3 : trouver u avec u^2 = -3 mod p (ou x = u, x = -u - 1 pour Eisenstein)
    for u in range(2, p):
        if (u * u + 3) % p == 0:
            break
    # Euclide etendu : a*u + b*p = 1 ; en ajustant on trouve a, b dans Z[omega].
    # Representation directe : pour p = 1 mod 3, il existe a, b avec p = a^2 + ab + b^2
    # et la solution peut se trouver par recherche directe dans le cercle de rayon sqrt(p).
    bound = int(p**0.5) + 2
    for a in range(1, bound):
        for b in range(a, bound):
            if a * a + a * b + b * b == p:
                return (a, b)
            if a * a + a * b + b * b > p:
                break
    return None

# Verification sur tous les premiers p <= 1000.
ok = 0; rep_1mod3 = 0; rep_2mod3 = 0
for p in premiers(1000):
    r = two_triangles(p)
    if p == 3 or p % 3 == 1:
        rep_1mod3 += 1
        if r and r[0]**2 + r[0]*r[1] + r[1]**2 == p and r[0] > 0 and r[1] > 0:
            ok += 1
    elif p % 3 == 2:
        rep_2mod3 += 1
        if r is None:
            ok += 1

