from math import isqrt
import math

def enumerate_reduced_forms(D):
    # Formes reduites PRIMITIVES ax^2 + bxy + cy^2 avec D = b^2 - 4ac
    # Conditions : -a < b <= a < c, ou 0 <= b <= a = c ; gcd(a,b,c)=1
    # (classes de l'ORDRE de discriminant D : les formes imprimitives,
    # ex. (2,2,2) pour D=-12, ne sont pas inversibles dans l'ordre -- le
    # groupe de classes de l'ordre ne compte que les primitives)
    assert D < 0 and D % 4 in (0, 1), f'D doit etre congru 0, 1 mod 4 (D = {D})'
    forms = []
    a_max = isqrt(abs(D) // 3) + 1
    for a in range(1, a_max + 1):
        for b in range(-a + 1, a + 1):
            if (b * b - D) % (4 * a) != 0:
                continue
            c = (b * b - D) // (4 * a)
            if c < a:
                continue
            if a == c and b < 0:
                continue
            if math.gcd(math.gcd(a, b), c) != 1:
                continue
            forms.append((a, b, c))
    return forms

def kronecker(d, p):
    if p == 2:
        if d % 2 == 0:
            return 0
        if d % 8 in (1, 7):
            return 1
        return -1
    if d % p == 0:
        return 0
    v = pow(d % p, (p - 1) // 2, p)
    return -1 if v == p - 1 else 1

def conductor(d):
    if d % 4 == 1:
        return abs(d)
    while d % 4 == 0:
        d //= 4
    return abs(d)

def chi_D(d, n):
    if n == 0:
        return 0
    if n < 0:
        return chi_D(d, -n)
    out = 1
    m = n
    e = 0
    while m % 2 == 0:
        m //= 2
        e += 1
    if e > 0:
        k2 = kronecker(d, 2)
        if k2 == 0:
            return 0
        out *= k2 ** e
    p = 3
    while m > 1 and p * p <= m:
        if m % p == 0:
            e = 0
            while m % p == 0:
                m //= p
                e += 1
            kp = kronecker(d, p)
            if kp == 0:
                return 0
            out *= kp ** e
        p += 2
    if m > 1:
        out *= kronecker(d, m)
    return out

def roots_of_unit_count(d):
    if d == -4:
        return 4
    if d == -3:
        return 6
    return 2

def L_1_chi_d(d, N):
    # Produit d'Euler tronque (cf. section 3) : L(1, chi_d) ~= prod_{p <= N} (1 - chi(p)/p)^(-1).
    # Un premier p avec chi(p) = 0 (p divisant le conducteur) n'entre pas : facteur local = 1.
    prod = 1.0
    for k in range(2, N + 1):
        is_p = k > 1
        for r in range(2, int(k**0.5) + 1):
            if k % r == 0:
                is_p = False
                break
        if is_p:
            chi = chi_D(d, k)
            if chi != 0:
                prod /= (1.0 - chi / k)
    return prod

