import time

def jacobi_with_count(d, n):
    if n <= 0 or n % 2 == 0:
        raise ValueError
    d = d % n
    if d == 0:
        return 0, 0
    out = 1
    iters = 0
    while True:
        iters += 1
        if d == 0:
            return 0, iters
        if d == 1:
            return out, iters
        e = 0
        while d % 2 == 0:
            d //= 2
            e += 1
        if e > 0:
            # (2/n) : -1 pour n = 3, 5 (mod 8) ; facteur applique e fois.
            n_mod_8 = n % 8
            if n_mod_8 in (3, 5):
                out *= (-1) ** e
        if d == 1:
            return out, iters
        d, n = n, d
        if (d - 1) * (n - 1) // 4 % 2 == 1:
            out = -out
        d = d % n
        if d == 0:
            return 0, iters

# Pire cas de l'algorithme d'Euclide : paires de Fibonacci consecutives
# (quotient 1 a chaque etape de la descente). F(k) est pair si k = 0 mod 3,
# donc k != 0 mod 3 garde n impair pour le symbole de Jacobi.
def fib_pair(k):
    a, b = 0, 1
    for _ in range(k - 1):
        a, b = b, a + b
    return b, a  # (F(k), F(k-1))

print('Complexite de jacobi_symbol : iterations vs taille de n (pire cas Fibonacci)')
print()
for k in [11, 14, 17, 20, 23, 26, 29, 32, 35, 38, 41]:
    n, d = fib_pair(k)
    t0 = time.perf_counter()
    sym, iters = jacobi_with_count(d, n)
    elapsed = (time.perf_counter() - t0) * 1e6
    print(f'k = {k:>3} : n = F(k) a {n.bit_length():>3} bits : iters = {iters:>3}, elapsed = {elapsed:>8.2f} us')

def kronecker_symbol(d, n):
    if n == 0:
        if d == 1 or d == -1:
            return 1
        return 0
    if n == 1:
        return 1
    if n < 0:
        if d % 4 == 1:
            sign = 1
        elif d % 4 == 3:
            sign = -1
        else:
            if d % 4 == 0:
                return 0
            sign = 1
        return sign * kronecker_symbol(d, -n)
    out = 1
    e = 0
    while n % 2 == 0:
        n //= 2
        e += 1
    if e > 0:
        d_mod_8 = d % 8
        if d_mod_8 in (1, 7):
            k2 = 1
        elif d_mod_8 in (3, 5):
            k2 = -1
        else:
            k2 = 0
        if k2 == 0:
            return 0
        out *= k2 ** e
    if n == 1:
        return out
    d = d % n
    if d == 0:
        return 0
    while True:
        if d == 0:
            return 0
        if d == 1:
            return out
        e = 0
        while d % 2 == 0:
            d //= 2
            e += 1
        if e > 0:
            # (2/n) : -1 pour n = 3, 5 (mod 8) ; facteur applique e fois.
            n_mod_8 = n % 8
            if n_mod_8 in (3, 5):
                out *= (-1) ** e
        if d == 1:
            return out
        d, n = n, d
        if (d - 1) * (n - 1) // 4 % 2 == 1:
            out = -out
        d = d % n
        if d == 0:
            return 0

