def is_fundamental_disc(D):
    # Discriminant quadratique fondamental (Python : D % 4 in (0, 1) garde
    # les D négatifs congrus à 1 mod 4, que % == 1 exclusait à tort).
    if D % 4 not in (0, 1):
        return False
    if D % 4 == 1:
        m = D
    else:
        m = D // 4
        if m % 4 not in (2, 3):
            return False
    n = abs(m)
    for d in range(2, isqrt(n) + 1):
        if n % (d * d) == 0:
            return False
    return True

