def min_squares(n):
    """Nombre minimal de carres pour representer n."""
    s = isqrt(n)
    if s * s == n:
        return 1
    # 2 carres ?
    for a in range(1, isqrt(n) + 1):
        b2 = n - a*a
        if b2 < 0:
            break
        b = isqrt(b2)
        if b * b == b2:
            return 2
    # 3 carres ?
    for a in range(1, isqrt(n) + 1):
        for b in range(a, isqrt(n - a*a) + 1):
            c2 = n - a*a - b*b
            if c2 < 0:
                break
            c = isqrt(c2)
            if c * c == c2:
                return 3
    return 4

